var e={preflight:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Szybka kontrola tylko do odczytu, czy drukarka jest gotowa do rozpoczęcia druku.`}},refresh:{t:0,b:{t:2,i:[{t:3}],s:`Sprawdź ponownie`}},checking:{t:0,b:{t:2,i:[{t:3}],s:`Sprawdzanie...`}},ready:{t:0,b:{t:2,i:[{t:3}],s:`Gotowa do druku`}},notReady:{t:0,b:{t:2,i:[{t:3}],s:`Niegotowa do druku`}},checks:{unreachable:{fail:{t:0,b:{t:2,i:[{t:3}],s:`Drukarka jest nieosiągalna`}}},klippy:{pass:{t:0,b:{t:2,i:[{t:3}],s:`Klipper jest gotowy`}},fail:{t:0,b:{t:2,i:[{t:3,v:`Klipper nie jest gotowy (stan: `},{t:4,k:`state`},{t:3,v:`)`}]}}},idle:{pass:{t:0,b:{t:2,i:[{t:3}],s:`Brak druku w toku`}},fail:{t:0,b:{t:2,i:[{t:3,v:`Druk jest już uruchomiony (`},{t:4,k:`state`},{t:3,v:`)`}]}}},homed:{pass:{t:0,b:{t:2,i:[{t:3}],s:`Wszystkie osie są wybazowane`}},fail:{t:0,b:{t:2,i:[{t:3,v:`Osie niewybazowane (`},{t:4,k:`axes`},{t:3,v:`); rozpoczęcie druku zwykle najpierw bazuje`}]}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Przewodnik`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Przewodnik po kontroli przed drukiem`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Zamknij`}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:`Czym jest kontrola przed drukiem?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Spojrzenie tylko do odczytu na to, czy drukarka jest gotowa do startu: nigdy niczego nie porusza ani nie zmienia, jedynie raportuje. Twarde blokady zmieniają werdykt na czerwony; ostrzeżenia informują, ale nie blokują.`}}},checks:{title:{t:0,b:{t:2,i:[{t:3}],s:`Co sprawdza`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Czy Klipper jest gotowy (nie wyłączony ani w błędzie), czy żaden druk już nie trwa oraz czy osie są wybazowane (informacyjnie, ponieważ rozpoczęcie druku zwykle najpierw bazuje).`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Słowniczek`}}}},glossary:{klippyState:{term:{t:0,b:{t:2,i:[{t:3}],s:`Stan Klippera`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Własny status Klippera - 'ready' oznacza, że jest połączony i bezczynny; 'shutdown' lub 'error' oznacza, że nie może drukować, dopóki nie zostanie wyczyszczony.`}}},homing:{term:{t:0,b:{t:2,i:[{t:3}],s:`Bazowanie`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Przesuwanie każdej osi do jej krańcówki, aby drukarka wiedziała, gdzie znajduje się głowica. Większość procedur rozpoczęcia druku bazuje automatycznie.`}}}}}}};export{e as default};